import { request } from "../api/legacy";
import type { Invoice } from "./types";

/**
 * Fetches one invoice from the invoices service via the legacy client.
 *
 * `request` returns `any`, so the body is checked here before it is
 * handed out as an `Invoice`; a malformed response rejects instead of
 * flowing downstream as a mistyped object.
